<template><section class="pa-5"><h3>Establecimientos de atención</h3><p>Cada establecimiento puede tener una CLUES. No se asignan establecimientos a consultas anteriores.</p><p v-if="error" role="alert">{{ error }}</p><ul><li v-for="row in rows" :key="row.id"><button type="button" :disabled="busy" @click="open(row.id)">{{ row.displayName }} — {{ row.active ? 'Activo' : 'Inactivo' }}</button></li></ul><button type="button" :disabled="busy" @click="open(null)">Nuevo establecimiento</button><form v-if="editing" @submit.prevent="save"><fieldset :disabled="busy"><label>Nombre del establecimiento<input v-model="form.displayName" maxlength="250" required></label><catalog-reference-field v-model="cluesRef" family="sis.establishments" label="CLUES, opcional" :disabled="busy" :errors="cluesErrors" /><label>Inicio de asignación<input v-model="form.validFrom" type="date"></label><label>Fin de asignación<input v-model="form.validTo" type="date"></label><label><input v-model="form.active" type="checkbox">Activo en este consultorio</label><p>La clave seleccionada conserva su versión del catálogo SIS. La captura manual queda no verificada.</p><button type="submit">Guardar establecimiento</button></fieldset></form><p role="status">{{ message }}</p></section></template>
<script>
import CatalogReferenceField from './CatalogReferenceField.vue';
import { DACore } from '../../services/config/axios.context';
import { authorizationContext,isCurrentAuthorization } from '../../security/authorizationContext';
const base='api/identity/establishments';
// A rejected CLUES is shown at its field in user terms; the capture is kept for correction.
const CLUES_ERRORS={CLUES_NOT_OPERATING:'La CLUES no está en operación en esa versión del catálogo SIS.',CLUES_NOT_IN_SIS_RELEASE:'La CLUES no aparece en esa versión del catálogo SIS.'};
const cluesError=r=>r&&r.status===400&&r.data&&r.data.field==='cluesRef'?(CLUES_ERRORS[r.data.code]||'Revisa la CLUES: 11 letras o números de una clave existente.'):null;
export default {
 components:{CatalogReferenceField},
 data:()=>({rows:[],form:{},id:null,revision:0,cluesRef:null,cluesErrors:[],editing:false,busy:false,error:'',message:'',context:null,alive:true}),
 watch:{cluesRef(){this.cluesErrors=[];}},
 mounted(){this.context=authorizationContext(this.$store);this.load();},beforeDestroy(){this.alive=false;},
 methods:{current(){return this.alive&&isCurrentAuthorization(this.context,this.$store);},async load(){try{const r=await DACore.get(base);if(!this.current())return;if(!r.success)throw new Error(r.message);this.rows=r.data;}catch(e){if(this.current())this.error=e.message;}},async open(id){if(this.editing&&!window.confirm('¿Descartar la captura actual y abrir otro establecimiento?'))return;this.error='';this.busy=true;try{let d={displayName:'',active:true,validFrom:null,validTo:null,revision:0};if(id){const r=await DACore.get(base+'/'+encodeURIComponent(id));if(!this.current())return;if(!r.success)throw new Error(r.message);d=r.data;}this.id=id;this.revision=d.revision;this.cluesRef=d.cluesRef||null;this.form={displayName:d.displayName,active:d.active,validFrom:d.validFrom,validTo:d.validTo};this.editing=true;}catch(e){this.error=e.message;}finally{this.busy=false;}},async save(){if(this.busy||!this.current())return;this.busy=true;this.error='';try{const data={identity:{...this.form,validFrom:this.form.validFrom||null,validTo:this.form.validTo||null,cluesRef:this.cluesRef},expectedRevision:this.revision};const r=this.id?await DACore.patch(base+'/'+encodeURIComponent(this.id),data):await DACore.post(base,data);if(!this.current())return;const clues=!r.success&&cluesError(r);if(clues){this.cluesErrors=[clues];throw new Error('Revisa la CLUES. Conservamos tu captura.');}if(!r.success)throw new Error(r.status===409?'El establecimiento cambió. Conservamos tu captura; recarga antes de conciliar.':r.message);this.id=r.data.id;this.revision=r.data.revision;this.message='Establecimiento guardado. Consulta la verificación de la CLUES en su campo.';await this.load();}catch(e){this.error=e.message||'No se confirmó el guardado. Conserva tu captura.';}finally{this.busy=false;}}}
};
</script>
<style scoped>form{max-width:700px}label{display:block;margin:12px 0}input:not([type=checkbox]){display:block;width:100%;border:1px solid #64748b;padding:9px;border-radius:4px}button{padding:10px;border:1px solid #64748b;margin:4px}fieldset{min-width:0}</style>
